const source = $json.body ?? $json;
const headers = $json.headers ?? {};
const nestedUtms = source.utms ?? {};

function clean(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function normalizeText(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function normalizeYesNo(value) {
  const normalized = normalizeText(value);
  if (!normalized) return '';
  if (['sim', 's', 'yes', 'y'].includes(normalized)) return 'Sim';
  if (['nao', 'n', 'no'].includes(normalized)) return 'Não';
  if (normalized.includes('parcial')) return 'Parcial';
  if (normalized.includes('nao sei') || normalized.includes('não sei') || normalized.includes('nao_sei')) return 'Não sei';
  return clean(value);
}

function normalizeArea(value) {
  const normalized = normalizeText(value);
  if (!normalized) return '';
  if (normalized.includes('plano') || normalized.includes('saude')) return 'Planos de saúde';
  if (normalized.includes('seguro')) return 'Seguros';
  if (normalized.includes('conta') && normalized.includes('bloque')) return 'Contas bloqueadas';
  if (normalized.includes('golpe') || normalized.includes('fraude') || normalized.includes('banc')) return 'Golpes bancários';
  if (normalized.includes('aerea') || normalized.includes('voo') || normalized.includes('bagagem')) return 'Companhias aéreas';
  if (normalized.includes('digital') || normalized.includes('reputacao') || normalized.includes('difamacao') || normalized.includes('perfil falso') || normalized.includes('imagem')) return 'Direito digital e reputação online';
  return clean(value);
}

function saoPauloTimestamp(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'America/Sao_Paulo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).format(date).replace(' ', 'T');
}

function makeLeadId(phone, timestamp) {
  const stamp = timestamp.replace(/\D/g, '').slice(0, 14);
  const last4 = (phone || '0000').slice(-4).padStart(4, '0');
  const random = Math.random().toString(36).slice(2, 7).toUpperCase();
  return `LD-${stamp.slice(0, 8)}-${stamp.slice(8, 14)}-${last4}-${random}`;
}

const cidadeEstado = clean(source.cidade_estado);
const cidadeEstadoParts = cidadeEstado.includes('/') ? cidadeEstado.split('/') : [];
const whatsapp = clean(source.whatsapp).replace(/\D/g, '');
const dataEntrada = saoPauloTimestamp();
const areaAtuacao = normalizeArea(source.area_atuacao || source.plataforma || source.rede_social);
const payload = {
  lead_id: makeLeadId(whatsapp, dataEntrada),
  data_entrada: dataEntrada,
  nome: clean(source.nome),
  whatsapp,
  email: clean(source.email),
  origem: clean(source.origem) || 'site_google_ads',
  area_atuacao: areaAtuacao,
  plataforma: areaAtuacao,
  conteudo_no_ar: normalizeYesNo(source.conteudo_no_ar),
  possui_provas: normalizeYesNo(source.possui_provas),
  prejuizo: clean(source.prejuizo),
  data_ocorrido: clean(source.data_ocorrido),
  link_perfil: clean(source.link_perfil || source.link_publicacao),
  detalhes_caso: clean(source.detalhes_caso || source.relato),
  cep: clean(source.cep),
  cidade: clean(source.cidade) || clean(cidadeEstadoParts[0]),
  estado: clean(source.estado) || clean(cidadeEstadoParts[1]),
  profissao: clean(source.profissao),
  renda_estimada: clean(source.renda_estimada),
  classificacao: '',
  urgencia: '',
  tipo_caso: '',
  resumo_ia: '',
  proximo_passo: '',
  responsavel: '',
  duplicado: 'Não',
  utm_source: clean(source.utm_source || nestedUtms.utm_source),
  utm_medium: clean(source.utm_medium || nestedUtms.utm_medium),
  utm_campaign: clean(source.utm_campaign || nestedUtms.utm_campaign),
  utm_content: clean(source.utm_content || nestedUtms.utm_content),
  utm_term: clean(source.utm_term || nestedUtms.utm_term),
  gclid: clean(source.gclid || nestedUtms.gclid),
  fbclid: clean(source.fbclid || nestedUtms.fbclid),
  page_url: clean(source.page_url || source.landing_page || nestedUtms.landing_page),
  user_agent: clean(source.user_agent || headers['user-agent']),
  ip: clean(source.ip || headers['x-forwarded-for'] || headers['x-real-ip']),
  status: 'Novo',
};

const missing = ['nome', 'whatsapp', 'detalhes_caso'].filter((field) => !payload[field]);

if (missing.length > 0) {
  return [
    {
      json: {
        success: false,
        validation_error: true,
        missing_fields: missing,
        data: dataEntrada,
        origem: payload.origem,
        tipo_erro: 'validacao_campos_obrigatorios',
        descricao: 'Campos obrigatórios ausentes: ' + missing.join(', '),
        payload: JSON.stringify(source),
        status_resolucao: 'Pendente',
        data_resolucao: '',
        message: 'Algumas informações obrigatórias não foram enviadas. Verifique nome, WhatsApp e relato.',
      },
    },
  ];
}

return [{ json: { success: true, ...payload } }];

