const lead = $items('Code | Normalizar Dados', 0, 0)[0].json;
const rows = $input.all().map((item) => item.json ?? {});
const duplicateRow = rows.find((row) => String(row.whatsapp ?? '').replace(/\D/g, '') === lead.whatsapp);

if (duplicateRow) {
  return [
    {
      json: {
        ...lead,
        duplicado: 'Sim',
        duplicate: true,
        duplicate_existing_lead_id: duplicateRow.lead_id ?? '',
        duplicate_message: 'Suas informações já foram recebidas anteriormente. A equipe responsável dará continuidade ao atendimento.',
      },
    },
  ];
}

return [{ json: { ...lead, duplicate: false } }];

return [
  {
    json: {
      data: new Date().toISOString(),
      lead_id: $json.lead_id,
      remetente: 'site',
      destinatario: 'equipe',
      mensagem: `Lead duplicado recebido para o WhatsApp ${$json.whatsapp}. Lead original: ${$json.duplicate_existing_lead_id || 'não identificado'}.`,
      status: 'duplicado',
      tipo_mensagem: 'duplicidade',
      canal: 'webhook',
    },
  },
];

