const lead = $items('Code | Verificar Duplicidade', 0, 0)[0].json;
const aiRaw = $input.first().json;

function extractAiPayload(raw) {
  if (raw && raw.resumo_ia) return raw;

  let content = raw?.message?.content
    ?? raw?.choices?.[0]?.message?.content
    ?? raw?.data?.choices?.[0]?.message?.content
    ?? raw?.text
    ?? raw?.output
    ?? raw?.content
    ?? '';

  if (typeof content !== 'string') content = JSON.stringify(content ?? {});
  const cleaned = content.replace(/```json/gi, '').replace(/```/g, '').trim();

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    return {
      resumo_ia: cleaned || 'Resumo não retornado pela IA. Revisar manualmente.',
      classificacao: 'medio',
      urgencia: 'media',
      tipo_caso: 'outro',
      proximo_passo: 'Revisar manualmente as informações e solicitar documentos ou contexto complementar, se necessário.',
    };
  }
}

const ai = extractAiPayload(aiRaw);
const allowedClassificacao = ['quente', 'medio', 'frio'];
const allowedUrgencia = ['alta', 'media', 'baixa'];
const allowedTipos = [
  'plano_saude',
  'seguro',
  'conta_bloqueada',
  'golpe_bancario',
  'companhia_aerea',
  'direito_digital',
  'outro',
];

return [
  {
    json: {
      lead_id: lead.lead_id,
      data_entrada: lead.data_entrada,
      nome: lead.nome,
      whatsapp: lead.whatsapp,
      email: lead.email,
      origem: lead.origem,
      area_atuacao: lead.area_atuacao,
      plataforma: lead.plataforma,
      conteudo_no_ar: lead.conteudo_no_ar,
      possui_provas: lead.possui_provas,
      prejuizo: lead.prejuizo,
      data_ocorrido: lead.data_ocorrido,
      link_perfil: lead.link_perfil,
      detalhes_caso: lead.detalhes_caso,
      cep: lead.cep,
      cidade: lead.cidade,
      estado: lead.estado,
      profissao: lead.profissao,
      renda_estimada: lead.renda_estimada,
      classificacao: allowedClassificacao.includes(ai.classificacao) ? ai.classificacao : 'medio',
      urgencia: allowedUrgencia.includes(ai.urgencia) ? ai.urgencia : 'media',
      tipo_caso: allowedTipos.includes(ai.tipo_caso) ? ai.tipo_caso : 'outro',
      resumo_ia: ai.resumo_ia ?? '',
      proximo_passo: ai.proximo_passo ?? '',
      responsavel: lead.responsavel ?? '',
      duplicado: lead.duplicado ?? 'Não',
      utm_source: lead.utm_source,
      utm_medium: lead.utm_medium,
      utm_campaign: lead.utm_campaign,
      utm_content: lead.utm_content,
      utm_term: lead.utm_term,
      gclid: lead.gclid,
      fbclid: lead.fbclid,
      page_url: lead.page_url,
      user_agent: lead.user_agent,
      ip: lead.ip,
      status: lead.status ?? 'Novo',
    },
  },
];

